INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Last Holiday', 'Last Holiday is set in a picturesque North Bohemian village during the holidays in year 2000, where a good little singer seeks refuge from an angry old man. You have to take care of all your needs, such as food, drink, cigarettes, beer, girls and just about everything that goes with village life.' FROM games WHERE igdb_id = 224568 ON CONFLICT (game_id, language_code) DO NOTHING;
