INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gargoyles Remastered', 'Gargoyles Remastered is an artfully crafted revival of the 1995 SEGA Genesis classic 16-bit side-scrolling platform adventure. Relive the epic journey of Goliath and the Gargoyles featuring enhanced visuals, animations, and SFX, all inspired by the acclaimed animated series. The world of Gargoyles comes to life with a level of detail that will thrill fans of the animated series and retro gaming enthusiasts alike. Experience classic gameplay that stays authentic to its predecessor while including new features such as achievements, gameplay rewind, and more!' FROM games WHERE igdb_id = 216282 ON CONFLICT (game_id, language_code) DO NOTHING;
