INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Green With Energy', 'A relaxing game where you become a power engineer and iteratively design, test and build power grid designs. Balance budget, efficiency, and environmental impact, across a variety of biomes and climates. Will you build resilient systems, or cobble something together with duct tape? It''s your choice.' FROM games WHERE igdb_id = 150841 ON CONFLICT (game_id, language_code) DO NOTHING;
