INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Limbus Company', 'Limbus Company is a darkly stylish turn-based strategy RPG from Project Moon, set in the same universe as Lobotomy Corporation and Library of Ruina. As the Manager of Limbus Company, you must command a crew of twelve "Sinners"—distorted individuals based on classic literature—aboard the Mephistopheles bus. Your mission is to retrieve the Golden Boughs, powerful relics scattered across the ruins of a dystopian City.
