INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Murder of Sonic the Hedgehog', 'A brand new Sonic experience from the minds of the Sonic Social team: The Murder of Sonic the Hedgehog is a visual novel, point-and-click adventure! It''s Amy Rose''s birthday and she''s hosting a murder mystery party on the Mirage Express. When Sonic becomes the game''s victim, everyone is off to get to the bottom of things. However, something feels a bit off - is this really an innocent game or something more sinister afoot?' FROM games WHERE igdb_id = 243385 ON CONFLICT (game_id, language_code) DO NOTHING;
