INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toree Jolly Jam', 'Toree Jolly Jam is a short little, speed based, one level 3D Platformer, in a wintery holiday coating, that rewards the player with certain goodies. Finishing the level will grant the player several bonus "presents" to choose from, containing different surprises. These could be anything from new characters (or multiple characters at once!) to completely different minigames. There is even an old fashioned retro styled "sound test" hidden in there somewhere (as pointless as it might be nowadays).' FROM games WHERE igdb_id = 279783 ON CONFLICT (game_id, language_code) DO NOTHING;
