INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hogwarts Legacy', 'Hogwarts Legacy is an immersive, open-world action RPG set in the world first introduced in the Harry Potter books. Now you can take control of the action and be at the center of your own adventure in the wizarding world. Embark on a journey through familiar and new locations as you explore and discover fantastic beasts, customize your character and craft potions, master spell casting, upgrade talents, and become the wizard you want to be. Discover the feeling of living at Hogwarts as you make allies, battle Dark wizards, and ultimately decide the fate of the wizarding world. Your legacy is what you make of it.' FROM games WHERE igdb_id = 136625 ON CONFLICT (game_id, language_code) DO NOTHING;
