INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ready or Not', 'Ready or Not is a tactical first person shooter which places you in the boots of an elite SWAT team, tasked with diffusing hostile situations in intense, claustrophobic environments. It''s set in a nondescript modern America, where an income disparity between the classes have become unsustainable and the country has been plunged into havoc. Bring order to chaos with up to 8 players in cooperative play, battle enemy squads in a close player-vs-player environment, or command AI in a striking single-player mode.' FROM games WHERE igdb_id = 28489 ON CONFLICT (game_id, language_code) DO NOTHING;
