INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bang-On Balls: Chronicles', 'A quirky, absolutely content-packed, destructible open-world sandbox adventure with combat, platforming, character customization, and collect-a-thon scavenger hunt experience. Play solo, 2-player split screen, or online co-op for up to 4 players. No paid cosmetic DLC nonsense.' FROM games WHERE igdb_id = 143882 ON CONFLICT (game_id, language_code) DO NOTHING;
