INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mediterranea Inferno', 'Mediterranea Inferno is a visual novel set in Southern Italy, following three estranged friends reuniting after a traumatic event. It explores themes of desire, guilt, and disillusionment through surreal imagery and branching dialogue. The game offers a stylized, experimental take on coming-of-age and queer identity.' FROM games WHERE igdb_id = 252528 ON CONFLICT (game_id, language_code) DO NOTHING;
