INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Piece Odyssey', 'One Piece Odyssey is an RPG that puts players in control of Luffy and the other Straw Hat Pirates in an open world. You can travel around an island embarking on quests, exploring dungeons, solving puzzles and battling creatures in turn-based combat. During fights, the crew is divided up between active members and reserve members. All characters receive EXP, regardless of whether they are part of the active party or not.' FROM games WHERE igdb_id = 194837 ON CONFLICT (game_id, language_code) DO NOTHING;
