INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deliver Us Mars', 'Deliver Us Mars is a sci-fi adventure game developed by KeokeN Interactive and released in 2023. It is a sequel to Deliver Us the Moon and follows the story of astronaut Kathy Johanson as she embarks on a mission to Mars to recover powerful colony ships known as the ARKs, which were stolen by a group called the Outward. The game combines exploration, puzzle-solving, and platforming elements as players navigate the harsh Martian environment and uncover the mysteries surrounding the disappearance of the ARKs.' FROM games WHERE igdb_id = 194740 ON CONFLICT (game_id, language_code) DO NOTHING;
