INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teslagrad 2', 'Teslagrad 2 is the sequel to the original Teslagrad, developed by Rain Games and released in 2023. This 2D puzzle platformer builds upon the magnetic and electrical mechanics of its predecessor, with players once again using these abilities to solve puzzles and traverse complex environments. Set in a new region, the game introduces new powers, enemies, and challenges, while maintaining the visual storytelling and atmospheric design characteristic of the series.' FROM games WHERE igdb_id = 214506 ON CONFLICT (game_id, language_code) DO NOTHING;
