INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ea-sports-ufc-5', 255901, '2023-10-26', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co71e9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4eql.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EA Sports UFC 5', 'EA Sports UFC 5 is as real as it gets. Powered by Frostbite engine’s advanced rendering capabilities, your favorite fighters now have unparalleled character likenesses to complement next-level environment fidelity that’ll make their walk to the Octagon feel like a PPV main event. The all-new authentic damage system brings the intensity and strategy of a fight to life, as cuts and strikes absorbed can affect mobility, defense, stamina, and more. Take too much damage, and the doctor will check to see if you’re able to continue. For lovers of the ground game, the new Transition-Based Submissions make grappling feel more fluid and realistic than ever before. And if you like to admire your handiwork, new Cinematic K.O. Replays capture your fight-ending finishes in all their punishing glory. Plus, a completely revamped live service schedule builds exciting challenges around all PPV fight weeks. Bring the next evolution of the fight game home with UFC 5.' FROM games WHERE igdb_id = 255901 ON CONFLICT (game_id, language_code) DO NOTHING;
