INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('railway-empire-2', 215138, '2023-05-25', 76, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co55m0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1tkw.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Railway Empire 2', 'In Railway Empire 2, grow your company into the largest railway company of the continent and outsmart your competitors as you connect cities and companies with an ever-expanding network of rail lines, bridges, and tunnels. Railway Empire 2 features bigger, more detailed and lively maps than ever before. The whole of the US and continental Europe are covered in two huge, sprawling maps, whilst more detailed maps put the focus on specific regions of each continent. Improved track construction helps you focus on the important decisions as you drive the economy and help the growth of the cities. Signals are placed automatically, bridges can hold up to 4 tracks and the expandable train stations can now have up to 8 tracks.' FROM games WHERE igdb_id = 215138 ON CONFLICT (game_id, language_code) DO NOTHING;
