INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mewnbase', 'MewnBase is a cute, 2D exploration/survival game. You land on an uncharted world only to realize you didn''t bring any snacks and forgot half your luggage. But hey, at least you brought this workbench thing. You''ll need to collect resources in order to construct a make-shift base. Craft a variety of different base modules, from airlocks to rain-water collectors in order to make your new home on this barren planet a little more cozy.' FROM games WHERE igdb_id = 54984 ON CONFLICT (game_id, language_code) DO NOTHING;
