INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tingus Goose', 'Tingus Goose is an idle game where you control a goose named Tingus that automatically moves and attacks. The goal is to collect treasure, defeat enemies, and upgrade Tingus'' abilities. The game features automatic gameplay with occasional manual interventions, allowing you to let Tingus run on its own while you do other things. You can upgrade Tingus'' abilities and equipment, collect treasure and resources, battle enemies and bosses, and explore different environments and levels.' FROM games WHERE igdb_id = 285342 ON CONFLICT (game_id, language_code) DO NOTHING;
