INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hello-kitty-island-adventure', 254871, '2023-07-28', 81, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coauri.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4p64.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hello Kitty Island Adventure', 'A cozy life sim/adventure hybrid featuring Hello Kitty and Friends. Create a unique, Sanrio-style original avatar and befriend iconic Sanrio characters like Kuromi, Badtz-Maru, Cinnamoroll, Chococat, and Aggretsuko. Share gifts, complete quests, and take part in island activities to deepen your bonds. Spruce up cabins to attract new visitors from among Hello Kitty’s many friends. Create a stylish wardrobe all your own, solve mysterious puzzles, cook delectable recipes, collect friendly critters, and fish, and explore the island solo or with a friend to unearth the many secrets of a massive in-game world.' FROM games WHERE igdb_id = 254871 ON CONFLICT (game_id, language_code) DO NOTHING;
