INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Time Bandit: Part 1 - Appendages of the Machine', 'A darkly comic life sim that unfolds slowly in real time. Manage your money, fuel, and energy while slowly solving puzzles to collect the time crystals and then pull off high-stakes stealthy heists. Steal back time from your employer in this anti-capitalist melodrama, told through lowpoly cutscenes and radio conversations inspired by classic cinematic games.' FROM games WHERE igdb_id = 165328 ON CONFLICT (game_id, language_code) DO NOTHING;
