INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Like a Dragon Gaiden: The Man Who Erased His Name', 'Like a Dragon Gaiden: The Man Who Erased His Name is a 2023 action-adventure video game developed by Ryu Ga Gotoku Studio and published by Sega. It is a spin-off of the Like a Dragon series. Taking place during the events of Yakuza: Like a Dragon (2020), Like a Dragon Gaiden focuses on the series'' original protagonist, Kazuma Kiryu, as he embarks on a new adventure in Osaka under the guise of a secret agent.' FROM games WHERE igdb_id = 217624 ON CONFLICT (game_id, language_code) DO NOTHING;
