INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goodbye Volcano High', 'Fang is a typical 18-year-old dinosaur: they’re more concerned about their band going viral than they are about what happens after graduation. But they’re about to have much bigger problems. Will they find time to figure themselves out? Can they balance a potential apocalypse and a budding romance? During hard times, what do we owe each other? Goodbye Volcano High is a cinematic narrative adventure about the beginning of a love story... and the end of an era.' FROM games WHERE igdb_id = 134589 ON CONFLICT (game_id, language_code) DO NOTHING;
