INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Remnant II', 'Remnant II is the sequel to the best-selling game Remnant: From the Ashes that pits survivors of humanity against new deadly creatures and god-like bosses across terrifying worlds. Play solo or co-op with two other friends to explore the depths of the unknown to stop an evil from destroying reality itself. To succeed, players will need to rely on their own skills and those of their team to overcome the toughest challenges and to stave off humanity’s extinction.' FROM games WHERE igdb_id = 228535 ON CONFLICT (game_id, language_code) DO NOTHING;
