INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Girls'' Frontline 2: Exilium', 'GIRLS'' FRONTLINE 2: EXILIUM is the official sequel to the mobile game Girls'' Frontline. It is a brand-new 3D Strategy RPG available for both mobile devices and PC, featuring a Non-Photorealistic Rendering (NPR) art style based on Physically Based Rendering (PBR) technology. The core gameplay focuses on turn-based tactics, while incorporating collection and RPG elements.' FROM games WHERE igdb_id = 174844 ON CONFLICT (game_id, language_code) DO NOTHING;
