INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Birth', 'Birth is a pleasantly creepy point-and-click puzzle game about living alone in a large city and constructing a creature to keep you company out of spare bones and organs you find lying around. Explore libraries, post offices, museums, cafes, and apartments that don''t belong to you, solving observational puzzles hidden in personal belongings and scenery.' FROM games WHERE igdb_id = 204378 ON CONFLICT (game_id, language_code) DO NOTHING;
