INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomb Rush Cyberfunk', 'Bomb Rush Cyberfunk, an indie action-adventure platformer, features 1 second per second of highly advanced funkstyle. In a world where self-styled crews are equipped with personal boostpacks, new heights of graffiti are reached. Start your own cypher and dance, paint, trick, face off with the cops and stake your claim to the extrusions and cavities of a sprawling metropolis in an alternate future.' FROM games WHERE igdb_id = 135940 ON CONFLICT (game_id, language_code) DO NOTHING;
