INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Chinese Ghost Story 2023', 'This game tells a touching love story. Ning Caichen is an scholar. On his way to Guobei County to collect accounts, he encountered heavy rain and had to hide in Lanruo Temple. In the temple, he met a pretty ghost named Nie Xiaoqian. later, they fell in love with each other, and the story unfolded...' FROM games WHERE igdb_id = 255182 ON CONFLICT (game_id, language_code) DO NOTHING;
