INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sludge Life 2', 'Big Mud is missing! Everyone''s favourite rapping frog has vanished, and his closest homie Ghost (that''s you) is on a mission to find him. Sludge Life 2 whisks you away to Ciggy City Suites, a luxurious multi-floor hotel heaving with secrets, gadgets, gags, peculiar characters, and ugly corporate architecture to make over with your spray can.' FROM games WHERE igdb_id = 242597 ON CONFLICT (game_id, language_code) DO NOTHING;
