INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Hominid Invasion', 'Alien Hominid Invasion is a co-op run ‘n’ gun packed with chaos, mayhem, and a whole lot of explosions. Unlock and equip an arsenal of weapons and boosts, level up, then beam down to invade Earth with up to three other friends. Abduct intel from your enemies to sabotage their plans, observe the oddities of human life, blow up bosses, and mutate into a variety of powerful Alien forms in order to take down the not-so-secret Agents that are dead set on ruining your day.' FROM games WHERE igdb_id = 131817 ON CONFLICT (game_id, language_code) DO NOTHING;
