INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hellsweeper VR', 'From the makers of Sairento VR comes a first person action-combat game that descends you into hell. In Hellsweeper VR you traverse the demonic dimensions, wield weapons with deadly precision, command the forces of telekinesis and muster mystical powers to wipe out your twisted enemies. Reap your rewards, upgrade your skills, and choose your fate as you experiment with unique combat variations and start to discover what being a Hellsweeper means to you.' FROM games WHERE igdb_id = 166324 ON CONFLICT (game_id, language_code) DO NOTHING;
