INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cubic Crush: Streamer Showdown', 'Come and show your skills in Cubic Crush Streamer Showdown! This 4D Tetris-style game is played in the rooms of your favorite Youtubers and offers different difficulty levels and missions to complete - use powerful powerups during the game to gain an advantage and advance even faster! Plus, in our interactive Twitch mode, your viewers can send you commands and help you succeed - unlock more rooms as you progress and become the king of Cubic Crush in this exciting challenge!' FROM games WHERE igdb_id = 230587 ON CONFLICT (game_id, language_code) DO NOTHING;
