INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Spooky Teaparty', 'Take the role of Rover, Summer, Britton and Marina in this fun, exploration-based Halloween adventure that takes place just after the events of Aplestia! Find treats, solve puzzles, battle with spooky monsters, enter secret rooms and meet with undead, funny characters! Welcome to Duruduru Castle!' FROM games WHERE igdb_id = 221172 ON CONFLICT (game_id, language_code) DO NOTHING;
