INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Homestead Arcana', 'Become a farming Witch and pioneer the range that has been mysteriously corrupted with Miasma. Discover the secret behind its appearance, grow plants to power up your spells, and use nature’s magic to heal the land. Build your very own homestead from the ground up. Discover new plants and tend to your ever-growing garden to heal the land and make it your own.' FROM games WHERE igdb_id = 217635 ON CONFLICT (game_id, language_code) DO NOTHING;
