INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spirittea', 204418, '2023-11-13', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5nw8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1oht.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spirittea', 'A slice-of-life RPG set in east Asia, Spirittea is a story about a city author heading out to a mountain town to pick up inspiration for their book. In doing so, they find a magical teapot that allows them to see into the spirit world. Strange occurrences plague the town, and it''s up to the player to find and appease the spirits by rebuilding their bathhouse and managing it to a high standard in order to allow them to soak away their troubles. This then frees up the townspeople, who will look to bond with you over food, games, karaoke, fishing and bug catching, giving you plenty of inspiration for your novel!' FROM games WHERE igdb_id = 204418 ON CONFLICT (game_id, language_code) DO NOTHING;
