INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Island 2', 'Dead Island 2 is a survival horror first-person shooter set in a zombie apocalypse in Los Angeles. Players explore an open world, gathering resources, interacting with survivors, and battling swarms of zombies in fast-paced combat. Set fifteen years after the events of Dead Island: Riptide, the game features a new cast of characters and narrative, while maintaining the series’ signature blend of brutal melee action and immersive environments.' FROM games WHERE igdb_id = 7329 ON CONFLICT (game_id, language_code) DO NOTHING;
