INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Small Saga', 'Small Saga is a turn-based RPG that takes place in a medieval rodent society beneath the streets of modern London. The story follows Verm, a particularly angry mouse armed with a pen knife, who is hunting for the human who stole his tail. On the way, Verm befriends a mole wizard, a squirrel harlequin, and a lab rat lancer. Together, the party upend rodent society, clash with titans, and eventually face off against the gods themselves.' FROM games WHERE igdb_id = 119278 ON CONFLICT (game_id, language_code) DO NOTHING;
