INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last Faith', 'The Last Faith is an exploration-based Metroidvania, action side-scrolling platformer with dark and gothic horror themes at its core. An ancient religion is ruling for centuries the world left to its fate. The once majestic capital and full of a glorious past, is now decadent and haunted by a fatal disease. Eric will have to subvert the words of the hidden prophecy and discover the truth behind the now corrupted and ravaged world.' FROM games WHERE igdb_id = 133896 ON CONFLICT (game_id, language_code) DO NOTHING;
