INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tea for God', 'Tea F\for God is a VR adventure that uses impossible spaces with procedural generation to allow players infinite movement within their own place. Customizable gameplay can be anything between a relaxing long walk, an intense arcade shooter (checkpoint based) and a roguelite shooter-explorer. Set in the distant future, it is a story about a man who has lost his family and embarks on his last journey to seek answers and vengeance.' FROM games WHERE igdb_id = 175782 ON CONFLICT (game_id, language_code) DO NOTHING;
