INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deadlink', 'Deadlink is a cyberpunk FPS with roguelite elements. You''re the first operative to be recruited to the experimental Deadlink project. Pilot an autonomous combat shell, fighting your way through cramped slums, twisted labs, grimy warehouses, and sleek office buildings on a mission to thwart the schemes of the most powerful corporations in the world. Wield a deadly arsenal, upgrade your skills and tech, devastate destructible environments, and slash corporate profit margins — all at the same time.' FROM games WHERE igdb_id = 204239 ON CONFLICT (game_id, language_code) DO NOTHING;
