INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RICE: Repetitive Indie Combat Experience', 'A rich paragraph of information which will try to charm and pique interest, trying to catch your eye in a sea of competition using a slew of buzzwords such as ‘bullet heaven’ and ‘in-depth meta-progression’, in a vain attempt to make you believe this game is any different from others in it’s genre.' FROM games WHERE igdb_id = 233692 ON CONFLICT (game_id, language_code) DO NOTHING;
