INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ea-sports-fc-24', 256092, '2023-09-29', 66, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6qqa.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2e4t.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EA Sports FC 24', 'EA SPORTS FC 24 is the ultimate football simulation game that lets you play as your favourite stars and teams in the most authentic and immersive way possible. With EA SPORTS FC, you can experience the thrill of the world''s biggest competitions, such as the Premier League, UEFA Champions League, UEFA Women''s Champions League, La Liga Santander, Bundesliga, Ligue 1, Serie A, CONMEBOL Libertadores, Barclays Women''s Super League, NWSL and many more. EA SPORTS FC 24 also features a new brand identity inspired by the triangles that have been part of EA SPORTS football for the past 30 years, from the isometric polygons that make up the game to the chemistry triangles that exist in Ultimate Team to the player indicator across every match. Join the Club and be part of a new Football Club for the future of football we want to build together.' FROM games WHERE igdb_id = 256092 ON CONFLICT (game_id, language_code) DO NOTHING;
