INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lonely League', 'The Lonely League is a comic book style superhero tactical fangame RPG with Superman, Batman, Venom and John Lennon. It alternates between comic book cutscenes and tactical battles inspired by games like Shining Force and Final Fantasy Tactics. Battles are challenging and deeply tactical, and there are always multiple paths to victory, which often include not only attacking but also interacting with map objects and recruiting temporary characters. The story develops from common errands of an ordinary guy, slowly escalating to an epic journey with psychological and political undertones.' FROM games WHERE igdb_id = 245004 ON CONFLICT (game_id, language_code) DO NOTHING;
