INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ad Infinitum', 'Ad Infinitum is an atmospheric single-player horror game, which puts you into a World War I setting seen through a first-person perspective. You find yourself in the trenches of a forlorn battlefield where your are being hunted by vicious creatures. Solve puzzles to clear pathways and sneak through trenches to hide from vicious creatures. Avoid dangerous threats and try to escape this world of pain and death. Besides the realistic graphics, the game features a stealth system, puzzle-solving and exploration of the vicious game world which all culminates in a subtle yet intense story.' FROM games WHERE igdb_id = 77338 ON CONFLICT (game_id, language_code) DO NOTHING;
